# rule A check: cells between consecutive sep rows (interior) and consecutive sep cols
def ruleA(grid, sep_rows, sep_cols, bg):
    R=len(sep_rows)-1; C=len(sep_cols)-1
    out=[[bg]*C for _ in range(R)]
    for i in range(R):
        for j in range(C):
            corners={int(grid[sep_rows[i+k]][sep_cols[j+l]]) for k in (0,1) for l in (0,1)}
            if len(corners)==1:
                v=corners.pop()
                if v!=7: out[i][j]=v
    return out
